contenido.valor:
# Generar solo el certificado (validación manual)
certbot certonly --webroot -w /var/www/html -d midominio.com -d www.midominio.com

# Configurar Nginx manualmente con el certificado
# /etc/nginx/sites-available/midominio.com
server {
    listen 443 ssl http2;
    server_name midominio.com www.midominio.com;

    ssl_certificate /etc/letsencrypt/live/midominio.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/midominio.com/privkey.pem;

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256;
    ssl_prefer_server_ciphers off;

    root /var/www/html;
    index index.html;
}

# Redirigir HTTP a HTTPS
server {
    listen 80;
    server_name midominio.com www.midominio.com;
    return 301 https://$host$request_uri;
}
